def count_good_plans(n, m, b, mod, bugs_per_programmer):
    from functools import lru_cache

    @lru_cache(None)
    def dp(programmer, lines_left, bugs_left):
        if programmer == n:
            return 1 if lines_left == 0 else 0
        if lines_left < 0 or bugs_left < 0:
            return 0

        total_plans = 0
        for lines in range(lines_left + 1):
            bugs_used = lines * bugs_per_programmer[programmer]
            if bugs_used <= bugs_left:
                total_plans += dp(programmer + 1, lines_left - lines, bugs_left - bugs_used)
                total_plans %= mod

        return total_plans

    return dp(0, m, b)

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    b = int(data[2])
    mod = int(data[3])
    bugs_per_programmer = list(map(int, data[4:4 + n]))

    result = count_good_plans(n, m, b, mod, bugs_per_programmer)
    print(result)
